/// like [`Self::invert_mask`]. Like invert, session-wide across sets.
pub fn clear_mask(&mut self) -> bool {
    if self.stroking {
        return false;
    }
    for mask in self.masks.values_mut() {
        mask.clear();
    }
    self.mask_synced.clear();
    true
}

